package com.example.app.model;

import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class User {

    private Long id;
    private String username;
    private String email;
}

package com.example.app.service;

import com.example.app.model.User;
import java.util.ArrayList;
import java.util.List;
import lombok.RequiredArgsConstructor;
import lombok.extern.java.Log;

@Log
@RequiredArgsConstructor
public class UserService {

    private final UserRepository repository;

    public User register(String username, String email) {
        log.info(() -> "Registering user " + username);
        User user = User.builder()
                .username(username)
                .email(email)
                .build();
        return repository.save(user);
    }

    public static class UserRepository {

        private final List<User> users = new ArrayList<>();

        public User save(User user) {
            user.setId((long) users.size() + 1);
            users.add(user);
            return user;
        }
    }
}

package com.example.app;

import com.example.app.model.User;
import com.example.app.service.UserService;
import com.example.app.service.UserService.UserRepository;

public class App {

    public static void main(String[] args) {
        UserService service = new UserService(new UserRepository());
        User user = service.register("jane", "jane@example.com");
        System.out.println(user);
    }
}

package com.example.app.model;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertNull;

import org.junit.jupiter.api.Test;

class UserTest {

    @Test
    void builderCreatesFullyPopulatedInstance() {
        User user = User.builder()
                .id(1L)
                .username("jane")
                .email("jane@example.com")
                .build();

        assertEquals("jane", user.getUsername());
        assertEquals("jane@example.com", user.getEmail());
    }

    @Test
    void settersAndGettersWork() {
        User user = new User();
        assertNull(user.getUsername());

        user.setUsername("john");

        assertEquals("john", user.getUsername());
    }

    @Test
    void equalsAndHashCodeAreGenerated() {
        User a = User.builder().id(1L).username("jane").build();
        User b = User.builder().id(1L).username("jane").build();
        User c = User.builder().id(2L).username("jane").build();

        assertEquals(a, b);
        assertEquals(a.hashCode(), b.hashCode());
        assertNotEquals(a, c);
    }
}

